from rdkit import Chem
smiles = 'COc1ccc(C)n2nc(CCc3nc(-c4ccccc4)nn3CCO)nc12'
mol = Chem.MolFromSmiles(smiles)
if mol:
    print('Valid SMILES')
    # Find the CCO group
    for atom in mol.GetAtoms():
        if atom.GetSymbol() == 'O':
            neighbors = [n.GetSymbol() for n in atom.GetNeighbors()]
            print(f'Oxygen with neighbors: {neighbors}')
else:
    print('Invalid SMILES')
"
"}

